package dev.danielc.fujiapp;
import android.content.*;
import android.graphics.*;
import android.net.Uri;
import android.os.Build;
import android.util.Size;
import java.io.*;
/** URI decoding off the main thread, with a bounded bitmap allocation. */
final class LocalMedia {
 static Bitmap decode(Context c,Uri uri,int edge)throws IOException {BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;try(InputStream in=c.getContentResolver().openInputStream(uri)){if(in==null)throw new FileNotFoundException();BitmapFactory.decodeStream(in,null,options);}if(options.outWidth<1||options.outHeight<1)return null;options.inSampleSize=PreviewSizing.sample(options.outWidth,options.outHeight,edge);options.inJustDecodeBounds=false;try(InputStream in=c.getContentResolver().openInputStream(uri)){if(in==null)throw new FileNotFoundException();Bitmap bitmap=BitmapFactory.decodeStream(in,null,options);if(bitmap==null||Build.VERSION.SDK_INT<24)return bitmap;try(android.os.ParcelFileDescriptor fd=c.getContentResolver().openFileDescriptor(uri,"r")){if(fd==null)return bitmap;android.media.ExifInterface exif=new android.media.ExifInterface(fd.getFileDescriptor());int orientation=exif.getAttributeInt(android.media.ExifInterface.TAG_ORIENTATION,1);Matrix matrix=new Matrix();switch(orientation){case 2:matrix.setScale(-1,1);break;case 3:matrix.setRotate(180);break;case 4:matrix.setScale(1,-1);break;case 5:matrix.setRotate(90);matrix.postScale(-1,1);break;case 6:matrix.setRotate(90);break;case 7:matrix.setRotate(-90);matrix.postScale(-1,1);break;case 8:matrix.setRotate(-90);break;default:return bitmap;}Bitmap upright=Bitmap.createBitmap(bitmap,0,0,bitmap.getWidth(),bitmap.getHeight(),matrix,true);if(upright!=bitmap)bitmap.recycle();return upright;}catch(IOException|RuntimeException ignored){return bitmap;}}}
 static Bitmap thumbnail(Context c,SavedLibrary.Photo photo){try{if(Build.VERSION.SDK_INT>=29&&"content".equals(photo.uri().getScheme())){try{Bitmap thumbnail=c.getContentResolver().loadThumbnail(photo.uri(),new Size(360,360),null);if(thumbnail!=null)return thumbnail;}catch(IOException|RuntimeException unsupported){/* Some providers do not implement thumbnails; decode the original below. */}}if(photo.kind()==3){android.media.MediaMetadataRetriever video=new android.media.MediaMetadataRetriever();try{video.setDataSource(c,photo.uri());if(Build.VERSION.SDK_INT>=27)return video.getScaledFrameAtTime(0,android.media.MediaMetadataRetriever.OPTION_CLOSEST_SYNC,360,360);return null;}finally{video.release();}}return decode(c,photo.uri(),360);}catch(Exception|OutOfMemoryError e){return null;}}
 static Uri shareUri(Context c,Uri uri){return "file".equals(uri.getScheme())?androidx.core.content.FileProvider.getUriForFile(c,c.getPackageName()+".files",new File(uri.getPath())):uri;}
 static void share(Context c,Uri uri,String name){try{uri=shareUri(c,uri);Intent send=new Intent(Intent.ACTION_SEND).setType(MediaFile.mime(name)).putExtra(Intent.EXTRA_STREAM,uri).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);send.setClipData(ClipData.newRawUri("照片",uri));c.startActivity(Intent.createChooser(send,"分享原文件"));}catch(RuntimeException e){android.widget.Toast.makeText(c,"文件不可用，可能已被移除",android.widget.Toast.LENGTH_LONG).show();}}
 static void open(Context c,Uri uri,String name){try{uri=shareUri(c,uri);Intent view=new Intent(Intent.ACTION_VIEW).setDataAndType(uri,MediaFile.mime(name)).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);view.setClipData(ClipData.newRawUri("文件",uri));c.startActivity(view);}catch(RuntimeException e){android.widget.Toast.makeText(c,"没有可打开此格式的应用，或文件已被移除",android.widget.Toast.LENGTH_LONG).show();}}
}
